package net.civeira.phylax.features.access.userprofile.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userprofile.domain.UserProfile;
import net.civeira.phylax.features.access.userprofile.domain.valueobject.PhoneNumberVO;

@RequiredArgsConstructor
public class PhoneNumberValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<PhoneNumberVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getPhoneNumber() {
    return value.flatMap(PhoneNumberVO::getPhoneNumber);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<PhoneNumberVO> getPhoneNumberValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param phoneNumber
   * @return
   */
  public T phoneNumber(PhoneNumberVO phoneNumber) {
    this.value = Optional.of(phoneNumber);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param phoneNumber
   * @return
   */
  public T phoneNumber(Optional<PhoneNumberVO> phoneNumber) {
    this.value = phoneNumber;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param phoneNumber
   * @return
   */
  public T phoneNumber(String phoneNumber) {
    this.value = Optional.of(PhoneNumberVO.from(phoneNumber));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T phoneNumberNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public PhoneNumberVO readPhoneNumber(final Optional<UserProfile> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(UserProfile::getPhoneNumberValue).orElseGet(PhoneNumberVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetPhoneNumber() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetPhoneNumberIfMatches(final String field) {
    if ("phoneNumber".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
